static bool is_end_with(const char * str1, const char * str2)
{
    if(str1 == NULL || str2 == NULL)
        return false;

    uint16_t len1 = strlen(str1);
    uint16_t len2 = strlen(str2);
    if((len1 < len2) || (len1 == 0 || len2 == 0))
        return false;

    while(len2 >= 1) {
        if(str2[len2 - 1] != str1[len1 - 1])
            return false;

        len2--;
        len1--;
    }

    return true;
}

static void strip_ext(char * dir)
{
    char * end = dir + strlen(dir);

    while(end >= dir && *end != '/') {
        --end;
    }

    if(end > dir) {
        *end = '\0';
    }
    else if(end == dir) {
        *(end + 1) = '\0';
    }
}

static const char* get_file_symbol(const char* filename) {
    // 返回基于文件扩展名的符号，或者NULL表示跳过
    if (is_end_with(filename, ".png") || is_end_with(filename, ".PNG") ||
        is_end_with(filename, ".jpg") || is_end_with(filename, ".JPG") ||
        is_end_with(filename, ".bmp") || is_end_with(filename, ".BMP") ||
        is_end_with(filename, ".gif") || is_end_with(filename, ".GIF")) {
        return LV_SYMBOL_IMAGE;
    }
    else if (is_end_with(filename, ".mp3") || is_end_with(filename, ".MP3")) {
        return LV_SYMBOL_AUDIO;
    }
    else if (is_end_with(filename, ".mp4") || is_end_with(filename, ".MP4") ||
             is_end_with(filename, ".avi") || is_end_with(filename, ".AVI")) {
        return LV_SYMBOL_VIDEO;
    }
    else if (filename[0] == '/') {
        return LV_SYMBOL_DIRECTORY;
    }
    else if (!is_end_with(filename, ".") && !is_end_with(filename, "..")) {
        return LV_SYMBOL_FILE;
    }
    return NULL;
}

#define MAX_FILES_VISIBLE 20  // 最大显示文件数量

static void showDir(const char* path) {
    char fn[LV_FILE_EXPLORER_PATH_MAX_LEN];
    uint16_t file_count = 0;
    lv_fs_dir_t dir;
    lv_fs_res_t res;
    lv_obj_t* obj = list1;
    lv_obj_t* btn;

    lv_obj_clean(obj);  // 清空现有列表

    // 创建表示当前路径和上一层路径的按钮
    //    btn = lv_list_add_btn(obj, LV_SYMBOL_DIRECTORY, ".");
    //    lv_obj_add_style(btn, &style, LV_PART_MAIN);
    //    lv_obj_set_style_bg_color(btn, lv_color_make(0, 0x40, 0xDD), LV_PART_MAIN | LV_STATE_FOCUSED);
    //    lv_group_add_obj(file_explorer_group, btn);
    //    lv_obj_add_event_cb(btn,file_explorerevent_handler,LV_EVENT_CLICKED, NULL);

    btn = lv_list_add_btn(obj, LV_SYMBOL_DIRECTORY, "..");
    lv_obj_add_style(btn, &style, LV_PART_MAIN);
    lv_obj_set_style_bg_color(btn, lv_color_make(0, 0x40, 0xDD), LV_PART_MAIN | LV_STATE_FOCUSED);
    lv_group_add_obj(file_explorer_group, btn);
    lv_obj_add_event_cb(btn,file_explorerevent_handler,LV_EVENT_CLICKED, NULL);

    res = lv_fs_dir_open(&dir, path);
    if (res != LV_FS_RES_OK) {
        LV_LOG_ERROR("Open dir error %d!", res);
        btn = lv_list_add_btn(obj, LV_SYMBOL_WARNING, "Open dir error !");
        lv_obj_add_style(btn, &style, LV_PART_MAIN);
        lv_obj_set_style_bg_color(btn, lv_palette_main(LV_PALETTE_RED), 0);

        if(res == LV_FS_RES_HW_ERR)
        {
            btn = lv_list_add_btn(obj, LV_SYMBOL_BELL, "Low level hardware error");
            lv_obj_add_style(btn, &style, LV_PART_MAIN);
            lv_obj_set_style_bg_color(btn, lv_palette_main(LV_PALETTE_RED), 0);
        }
        else if (res == LV_FS_RES_FS_ERR)
        {
            btn = lv_list_add_btn(obj, LV_SYMBOL_BELL, "Error in the file system structure");
            lv_obj_add_style(btn, &style, LV_PART_MAIN);
            lv_obj_set_style_bg_color(btn, lv_palette_main(LV_PALETTE_RED), 0);
        }
        else if (res == LV_FS_RES_NOT_EX)
        {
            btn = lv_list_add_btn(obj, LV_SYMBOL_BELL, "Driver, file or directory is not exists");
            lv_obj_add_style(btn, &style, LV_PART_MAIN);
            lv_obj_set_style_bg_color(btn, lv_palette_main(LV_PALETTE_RED), 0);
        }
        else if (res == LV_FS_RES_FULL)
        {
            btn = lv_list_add_btn(obj, LV_SYMBOL_BELL, "Disk full");
            lv_obj_add_style(btn, &style, LV_PART_MAIN);
            lv_obj_set_style_bg_color(btn, lv_palette_main(LV_PALETTE_RED), 0);
        }
        else if (res == LV_FS_RES_LOCKED)
        {
            btn = lv_list_add_btn(obj, LV_SYMBOL_BELL, "The file is already opened");
            lv_obj_add_style(btn, &style, LV_PART_MAIN);
            lv_obj_set_style_bg_color(btn, lv_palette_main(LV_PALETTE_RED), 0);
        }
        else if (res == LV_FS_RES_DENIED)
        {
            btn = lv_list_add_btn(obj, LV_SYMBOL_BELL, "Access denied. Check 'fs_open' modes and write protect");
            lv_obj_add_style(btn, &style, LV_PART_MAIN);
            lv_obj_set_style_bg_color(btn, lv_palette_main(LV_PALETTE_RED), 0);
        }
        else if (res == LV_FS_RES_BUSY)
        {
            btn = lv_list_add_btn(obj, LV_SYMBOL_BELL, "The file system now can't handle it, try later");
            lv_obj_add_style(btn, &style, LV_PART_MAIN);
            lv_obj_set_style_bg_color(btn, lv_palette_main(LV_PALETTE_RED), 0);
        }
        else if (res == LV_FS_RES_TOUT)
        {
            btn = lv_list_add_btn(obj, LV_SYMBOL_BELL, "Process time outed");
            lv_obj_add_style(btn, &style, LV_PART_MAIN);
            lv_obj_set_style_bg_color(btn, lv_palette_main(LV_PALETTE_RED), 0);
        }
        else if (res == LV_FS_RES_NOT_IMP)
        {
            btn = lv_list_add_btn(obj, LV_SYMBOL_BELL, "Requested function is not implemented");
            lv_obj_add_style(btn, &style, LV_PART_MAIN);
            lv_obj_set_style_bg_color(btn, lv_palette_main(LV_PALETTE_RED), 0);
        }
        else if (res == LV_FS_RES_OUT_OF_MEM)
        {
            btn = lv_list_add_btn(obj, LV_SYMBOL_BELL, "Not enough memory for an internal operation");
            lv_obj_add_style(btn, &style, LV_PART_MAIN);
            lv_obj_set_style_bg_color(btn, lv_palette_main(LV_PALETTE_RED), 0);
        }
        else if (res == LV_FS_RES_INV_PARAM)
        {
            btn = lv_list_add_btn(obj, LV_SYMBOL_BELL, "Invalid parameter among arguments");
            lv_obj_add_style(btn, &style, LV_PART_MAIN);
            lv_obj_set_style_bg_color(btn, lv_palette_main(LV_PALETTE_RED), 0);
        }
        else if (res == LV_FS_RES_UNKNOWN)
        {
            btn = lv_list_add_btn(obj, LV_SYMBOL_BELL, "Other unknown error");
            lv_obj_add_style(btn, &style, LV_PART_MAIN);
            lv_obj_set_style_bg_color(btn, lv_palette_main(LV_PALETTE_RED), 0);
        }
        return;
    }

    // 读取目录项并添加到列表，直到达到文件数量限制
    while (file_count < MAX_FILES_VISIBLE) {
        res = lv_fs_dir_read(&dir, fn);
        if (res != LV_FS_RES_OK) {
            LV_LOG_ERROR("Read dir error %d!", res);
            break;
        }
        if (fn[0] == '\0') {
            break;
        }

        // 根据文件类型选择符号
        const char * symbol = get_file_symbol(fn);

        if (symbol) {
            btn = lv_list_add_btn(obj, symbol, fn);
            lv_obj_add_style(btn, &style, LV_PART_MAIN);
            lv_obj_set_style_bg_color(btn, lv_color_make(0, 0x40, 0xDD), LV_PART_MAIN | LV_STATE_FOCUSED);
            lv_group_add_obj(file_explorer_group, btn);
            lv_obj_add_event_cb(btn,file_explorerevent_handler,LV_EVENT_CLICKED, NULL);

            lv_obj_t* label = lv_obj_get_child(btn, 1);
            lv_label_set_long_mode(label, LV_LABEL_LONG_WRAP);

            file_count++;
        }
    }

    lv_fs_dir_close(&dir);
    lv_event_send(obj, LV_EVENT_READY, NULL);
    lv_obj_scroll_to_y(obj, 0, LV_ANIM_OFF);
    lv_snprintf(current_path, sizeof(current_path), "%s", path);
}

extern uint8_t current_path_return;
extern char choose_device_path[LV_FILE_EXPLORER_PATH_MAX_LEN];
