void file_explorerevent_handler(lv_event_t *e)
{
    const char *str_fn = NULL;
    char file_name[LV_FILE_EXPLORER_PATH_MAX_LEN];
    lv_obj_t *obj = lv_group_get_focused(file_explorer_group);
    str_fn = lv_list_get_btn_text(list1, obj);
    LV_LOG_TRACE("selected entry: %s", str_fn);
    if ((strcmp(str_fn, ".") == 0))
        return;

    if (strcmp(str_fn, "..") == 0 && strlen(current_path) <= 3)
    {
        if (current_path_return == 3)
        {
            current_screen_set(SCREEN_MENU);
            _ui_screen_change(&ui_Menu, LV_SCR_LOAD_ANIM_FADE_ON, 300, 0, &ui_Menu_screen_init);
        }
        return;
    }

    if ((strcmp(str_fn, "..") == 0) && (strlen(current_path) > 3))
    {
        strip_ext(current_path);
        /*Remove the last '/' character*/
        strip_ext(current_path);
        lv_snprintf((char *)file_name, sizeof(file_name), "%s", current_path);
    }
    else
    {
       if (strcmp(str_fn, "..") != 0)
       {
          lv_snprintf((char *)file_name, sizeof(file_name), "%s%s",
                      current_path, str_fn);
       }
    }

    lv_fs_dir_t dir;
    LV_LOG_TRACE("open path: %s", file_name);
    if (lv_fs_dir_open(&dir, file_name) == LV_FS_RES_OK)
    {
        lv_fs_dir_close(&dir);
        showDir(file_name);
    }
    else
    {
		lv_snprintf((char *)file_name, sizeof(file_name), "%s/%s",current_path, str_fn);
        if (current_path_return == 1)
        {
            current_path_return = 0;
            lv_snprintf(current_path, sizeof(current_path), "%s", file_name);
            rt_strncpy(choose_device_path, rt_strstr(current_path, "/"),
                       sizeof(current_path) - 2);
            lv_label_set_text(ui_currentDevicePath, choose_device_path);
            current_screen_set(SCREEN_OFFLINE_DOWNLOAD);
            lv_disp_load_scr(ui_OfflineDownload);
            return;
        }
        else if (current_path_return == 2)
        {
            current_path_return = 0;
            lv_snprintf(current_path, sizeof(current_path), "%s", file_name);
            rt_strncpy(choose_firmware_bin_path,
                       rt_strstr(current_path, "/"),
                       sizeof(current_path) - 2);
            lv_label_set_text(ui_currentBinPath, choose_firmware_bin_path);
            current_screen_set(SCREEN_OFFLINE_DOWNLOAD);
            lv_disp_load_scr(ui_OfflineDownload);
            return;
        }
    }
}

